#[cfg(test)]
mod conformance {
    //! Round-trip tests harvested from the spec's `spec.md`,
    //! plus a `rejects_invalid_examples` test for any fixtures
    //! in `payload.invalid-examples.json` (validate feature).
    #[test]
    fn request_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:00000000-0000-4000-8000-000000000001\",\n  \"type\": \"https://trusttasks.org/spec/vtc/registry/sync-jobs/retry/0.1#request\",\n  \"issuer\": \"did:example:administrator\",\n  \"recipient\": \"did:example:community\",\n  \"issuedAt\": \"2026-01-01T00:00:00Z\",\n  \"threadId\": \"urn:uuid:00000000-0000-4000-8000-0000000000ff\",\n  \"payload\": {\n    \"jobId\": \"07c6c189-8272-4761-96e9-0ef869380665\"\n  }\n}\n";
        let doc: crate::TrustTask<super::Payload> =
            serde_json::from_str(JSON).expect("deserialize request example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "request example failed round-trip");
    }
    #[test]
    fn request_example_2() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:00000000-0000-4000-8000-000000000003\",\n  \"type\": \"https://trusttasks.org/spec/vtc/registry/sync-jobs/retry/0.1#request\",\n  \"issuer\": \"did:example:administrator\",\n  \"recipient\": \"did:example:community\",\n  \"issuedAt\": \"2026-01-01T00:00:00Z\",\n  \"threadId\": \"urn:uuid:00000000-0000-4000-8000-00000000010f\",\n  \"payload\": {\n    \"allFailed\": true\n  }\n}\n";
        let doc: crate::TrustTask<super::Payload> =
            serde_json::from_str(JSON).expect("deserialize request example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "request example failed round-trip");
    }
    #[test]
    fn response_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:00000000-0000-4000-8000-000000000002\",\n  \"type\": \"https://trusttasks.org/spec/vtc/registry/sync-jobs/retry/0.1#response\",\n  \"issuer\": \"did:example:community\",\n  \"recipient\": \"did:example:administrator\",\n  \"issuedAt\": \"2026-01-01T00:00:01Z\",\n  \"threadId\": \"urn:uuid:00000000-0000-4000-8000-0000000000ff\",\n  \"payload\": {\n    \"requeued\": [\n      {\n        \"jobId\": \"07c6c189-8272-4761-96e9-0ef869380665\",\n        \"memberDid\": \"did:example:member\"\n      }\n    ],\n    \"skipped\": [\n      {\n        \"jobId\": \"1f2e3d4c-5b6a-4798-8765-43210fedcba9\",\n        \"reason\": \"notFailed\"\n      }\n    ]\n  }\n}\n";
        let doc: crate::TrustTask<super::Response> =
            serde_json::from_str(JSON).expect("deserialize response example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "response example failed round-trip");
    }
    /// Each fixture in `payload.invalid-examples.json` MUST be
    /// rejected by at least one of: serde deserialization, or
    /// JSON-Schema validation under the `validate` feature. The
    /// fixture file documents the producer-side bug class that
    /// each payload exemplifies; this generated test pins it.
    #[cfg(feature = "validate")]
    #[test]
    fn rejects_invalid_examples() {
        use crate::validate::ValidatedPayload;
        let fixtures: &[(&str, &str)] = &[
            (
                "Neither jobId nor allFailed. The oneOf makes the discriminator mandatory — an empty payload must not be readable as 'retry everything'.",
                "{}",
            ),
            (
                "Both jobId and allFailed. Ambiguous intent: a consumer would have to choose between one job and all of them, so the schema refuses rather than letting each implementation pick.",
                "{\n  \"allFailed\": true,\n  \"jobId\": \"07c6c189-8272-4761-96e9-0ef869380665\"\n}",
            ),
            (
                "allFailed: false. The const pins it to true so the member means 'do the bulk operation' and never 'do something else'; a false here is a client that meant to send jobId.",
                "{\n  \"allFailed\": false\n}",
            ),
            (
                "Empty jobId. minLength 1 stops a dropped identifier arriving as a well-formed request naming nothing.",
                "{\n  \"jobId\": \"\"\n}",
            ),
            (
                "Unknown top-level member — additionalProperties: false catches `force`, which a caller might assume exists by analogy with other queue operations.",
                "{\n  \"force\": true,\n  \"jobId\": \"07c6c189-8272-4761-96e9-0ef869380665\"\n}",
            ),
            (
                "Bare/unnamespaced ext key — SPEC §4.5.1 requires every immediate child of ext to be reverse-DNS namespaced.",
                "{\n  \"ext\": {\n    \"reason\": \"operator retry\"\n  },\n  \"jobId\": \"07c6c189-8272-4761-96e9-0ef869380665\"\n}",
            ),
        ];
        for (i, (note, raw)) in fixtures.iter().enumerate() {
            let value: serde_json::Value = match serde_json::from_str(raw) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let serde_ok = serde_json::from_value::<super::Payload>(value.clone()).is_ok();
            let schema_ok = super::Payload::validate_value(&value).is_ok();
            assert!(
                !(serde_ok && schema_ok),
                "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
                i + 1,
                note,
                raw
            );
        }
    }
}
